import re
from typing import List, Dict, Any, Tuple, Optional

# helper regexes
_OBJ_RE = re.compile(r'^Object\s+(\d+):')
_FRAME_RE = re.compile(r'^Frame\s+(\d+):')
_COLLIDE_RE = re.compile(r'Object\s+(\d+).*collides with Object\s+(\d+)')
_INVIEW_RE = re.compile(r'Object\s+(\d+).*in view when the video begins')

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return all distinct entities in the given scope.
    Each entity has an id (string numeric) and a human‑readable description.
    """
    scope_node = node_by_title(doc, scope)
    objs = []
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child.get('kind') == 'list' and child.get('title').endswith(': Objects'):
            for line in child.get('lines', []):
                m = _OBJ_RE.match(line)
                if m:
                    eid = m.group(1)
                    desc = line.split(':', 1)[1].strip()
                    objs.append({"id": eid, "description": desc})
    return objs

def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    Return the maximum frame number observed in the Motion log.
    """
    mlog = None
    scope_node = node_by_title(doc, scope)
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child.get('kind') == 'table' and child.get('title').endswith(': Motion log'):
            mlog = child
            break
    if not mlog:
        return None
    max_frame = -1
    for _, row in table_rows(mlog):
        try:
            f = int(row.get('frame', -1))
            if f > max_frame:
                max_frame = f
        except Exception:
            pass
    return float(max_frame) if max_frame >= 0 else None

def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return all external inputs for the scope.
    """
    scope_node = node_by_title(doc, scope)
    ents = {e["id"]: e for e in entities(doc, scope)}
    inputs: List[Dict[str, Any]] = []

    # -- 1. initial motion states (first record per entity)
    mlog = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child.get('kind') == 'table' and child.get('title').endswith(': Motion log'):
            mlog = child
            break

    if mlog:
        # track first occurrence per entity id
        first_seen: Dict[str, Tuple[int, Dict[str, Any]]] = {}
        for idx, row in table_rows(mlog):
            oid = row.get('object', '').split(' ', 1)[0]  # id is first token of object field
            if oid not in first_seen:
                first_seen[oid] = (idx, row)

        inp_id_counter = 0
        for e_id, (row_idx, row) in first_seen.items():
            src = [mlog['node_id'], row_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']]
            inp = {
                "id": f"inp_state_{e_id}",
                "time": float(row.get('frame', 0)),
                "kind": "initial_state",
                "entities": [e_id],
                "fields": {
                    "x": float(row.get('x', 0)),
                    "y": float(row.get('y', 0)),
                    "vx": float(row.get('vx', 0)),
                    "vy": float(row.get('vy', 0)),
                    "speed": float(row.get('speed', 0)),
                },
                "src": src,
            }
            inputs.append(inp)
            inp_id_counter += 1

    # -- 2. explicit appearance events in Events list
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child.get('kind') == 'list' and child.get('title').endswith(': Events'):
            for line_idx, line in enumerate(child.get('lines', [])):
                mfr = _FRAME_RE.match(line)
                if not mfr:
                    continue
                frame = float(mfr.group(1))
                m_inview = _INVIEW_RE.search(line)
                if m_inview:
                    e_id = m_inview.group(1)
                    if e_id in ents:
                        src = [child['node_id'], line_idx]
                        inp = {
                            "id": f"inp_appear_{e_id}_{frame}",
                            "time": frame,
                            "kind": "appearance",
                            "entities": [e_id],
                            "fields": {},
                            "src": src,
                        }
                        inputs.append(inp)
    return inputs

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return all events that are produced by the process.
    """
    scope_node = node_by_title(doc, scope)
    ents = {e["id"]: e for e in entities(doc, scope)}
    outcomes: List[Dict[str, Any]] = []
    rec_end = recorded_end(doc, scope)

    # -- 3. collision events in Events list
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child.get('kind') == 'list' and child.get('title').endswith(': Events'):
            for line_idx, line in enumerate(child.get('lines', [])):
                mfr = _FRAME_RE.match(line)
                if not mfr:
                    continue
                frame = float(mfr.group(1))
                if rec_end is not None and frame > rec_end:
                    continue
                mc = _COLLIDE_RE.search(line)
                if mc:
                    e1, e2 = mc.group(1), mc.group(2)
                    if e1 in ents and e2 in ents:
                        src = [child['node_id'], line_idx]
                        out = {
                            "time": frame,
                            "kind": "collision",
                            "entities": [e1, e2],
                            "value": None,
                            "src": src,
                        }
                        outcomes.append(out)

    # -- 4. exit events (optional, as an outcome)
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child.get('kind') == 'list' and child.get('title').endswith(': Events'):
            for line_idx, line in enumerate(child.get('lines', [])):
                mfr = _FRAME_RE.match(line)
                if not mfr:
                    continue
                frame = float(mfr.group(1))
                if rec_end is not None and frame > rec_end:
                    continue
                if "exits" in line:
                    m_obj = re.search(r'Object\s+(\d+)', line)
                    if m_obj:
                        e_id = m_obj.group(1)
                        if e_id in ents:
                            src = [child['node_id'], line_idx]
                            out = {
                                "time": frame,
                                "kind": "exit",
                                "entities": [e_id],
                                "value": None,
                                "src": src,
                            }
                            outcomes.append(out)
    return outcomes

