_INVIEW_RE = re.compile(r"Object\s+(\d+)\s+.*in view when the video begins")
_COLLIDE_RE = re.compile(r"Object\s+(\d+)\s+.*collides with Object\s+(\d+)")
_EXIT_RE = re.compile(r"Object\s+(\d+)\s+.*exits")

