    """Return all distinct entities in the given scope."""
    scope_node = node_by_title(doc, scope)
    ents: List[Dict[str, str]] = []
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Objects"):
            for line in child.get("lines", []):
                m = _OBJ_RE.match(line)
                if m:
                    ents.append({"id": m.group(1), "description": m.group(2).strip()})
    return ents

def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Maximum frame number appearing in the motion log of the scope."""
    mlog = None
    scope_node = node_by_title(doc, scope)
    for child in children(doc, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            mlog = child
            break
    if not mlog:
        return None
    max_f = -1
    for row_index, row in table_rows(mlog):
        try:
            f = int(row.get("frame", -1))
            if f > max_f:
                max_f = f
        except Exception:
            pass
    return float(max_f) if max_f >= 0 else None

